// Aggregate upstream data, build the DeepSeek prompt, and forward chart / trade / pool data to the render step.
const ohlcvResp = $('Fetch OHLCV').first().json;
const tradesResp = $('Fetch Trades').first().json;
const poolInfoResp = $('Fetch Pool Info').first().json;
const goplusRaw = $('Fetch GoPlus').first().json;
const honeypotRaw = $('Fetch Honeypot').first().json;
const q = $('Set Query').first().json;

const poolAddress = q.address || '';
const candles = (ohlcvResp.data && ohlcvResp.data.attributes && ohlcvResp.data.attributes.ohlcv_list) || [];
const trades = tradesResp.data || [];
const poolAttrs = (poolInfoResp.data && poolInfoResp.data.attributes) || {};

const name = poolAttrs.name || 'Unknown';
const volume24h = parseFloat((poolAttrs.volume_usd && poolAttrs.volume_usd.h24) || 0);
const createdAt = poolAttrs.pool_created_at || '';

// Liquidity sanity check: liquidity >> 24h volume usually means bad data or manipulation.
let liquidity = parseFloat(poolAttrs.reserve_in_usd || 0);
let liquidityWarning = '';
if (volume24h > 0 && liquidity > volume24h * 50) {
  liquidityWarning = ' ⚠️ anomaly (liquidity far exceeds volume; possible manipulation or bad API data)';
}
const liquidityLine = '$' + liquidity.toFixed(2) + liquidityWarning;

// Downsample candles to at most 30 to keep the prompt short.
let sampled = [];
if (candles.length <= 30) { sampled = candles; }
else {
  const step = candles.length / 30;
  for (let i = 0; i < 30; i++) sampled.push(candles[Math.floor(i * step)]);
}
const candleLines = sampled.map(function(c) {
  return 'T=' + c[0] + ' O=' + Number(c[1]).toPrecision(6) + ' H=' + Number(c[2]).toPrecision(6) + ' L=' + Number(c[3]).toPrecision(6) + ' C=' + Number(c[4]).toPrecision(6) + ' V=' + Number(c[5]).toFixed(2);
}).join('\n');

// Unique wallet / active wallet stats, based on the first 200 trades only.
const walletCount = {};
const walletStats = {};
for (let i = 0; i < trades.length && i < 200; i++) {
  const t = trades[i];
  const a = t.attributes || {};
  const from = a.tx_from_address || 'unknown';
  const kind = (a.kind || '').toLowerCase();
  if (!walletCount[from]) { walletCount[from] = 0; walletStats[from] = { buys: 0, sells: 0 }; }
  walletCount[from]++;
  if (kind === 'buy') walletStats[from].buys++;
  else walletStats[from].sells++;
}

const totalTrades = trades.length;
const uniqueWallets = Object.keys(walletCount).length;
const topWalletsArr = Object.entries(walletCount).sort(function(a, b) { return b[1] - a[1]; }).slice(0, 8);
const topWallets = topWalletsArr.map(function(e) {
  const addr = e[0];
  const count = e[1];
  const s = walletStats[addr];
  return '  ' + addr.slice(0, 12) + ': ' + count + ' trades (buys ' + s.buys + ' / sells ' + s.sells + ')';
}).join('\n');

const recentTrades = trades.slice(0, 25).map(function(t) {
  const a = t.attributes || {};
  const time = (a.block_timestamp || '').slice(11, 19);
  const kind = (a.kind || '').toUpperCase();
  const usd = parseFloat(a.volume_in_usd || 0).toFixed(2);
  const from = (a.tx_from_address || '').slice(0, 12);
  const isBuy = (a.kind || '').toLowerCase() === 'buy';
  const price = isBuy
    ? parseFloat(a.price_to_in_usd || 0)
    : parseFloat(a.price_from_in_usd || 0);
  const priceText = price > 0 ? price.toPrecision(6) : '-';
  return '  ' + time + ' ' + kind + ' $' + usd + ' @ ' + priceText + ' ' + from;
}).join('\n');

const uniqueRatio = totalTrades > 0 ? ((uniqueWallets / totalTrades) * 100).toFixed(1) : '0';

// ---- GoPlus ----
// Structure: { code, message, result: { <tokenAddress>: {...} } }
// Empty result means no security data, which must NOT be treated as safe.
let goplus = {};
let goplusAvailable = false;
try {
  const result = goplusRaw.result || {};
  const keys = Object.keys(result);
  if (keys.length > 0) { goplus = result[keys[0]] || {}; goplusAvailable = true; }
} catch (e) { goplus = {}; }

const isHoneypot = goplus.is_honeypot === '1' ? 'yes ⚠️' : 'no';
const buyTax = goplus.buy_tax || '0';
const sellTax = goplus.sell_tax || '0';
const isMintable = goplus.is_mintable === '1' ? 'yes ⚠️' : 'no';
const isOpenSource = goplus.is_open_source === '1' ? 'yes' : 'no';
const hiddenOwner = goplus.hidden_owner === '1' ? 'yes ⚠️' : 'no';
const canTakeBack = goplus.can_take_back_ownership === '1' ? 'yes ⚠️' : 'no';
const ownerPercent = goplus.owner_percent || '0';
const creatorPercent = goplus.creator_percent || '0';
const holderCount = goplus.holder_count || 'N/A';
const lpHolderCount = goplus.lp_holder_count || 'N/A';
const isBlacklisted = goplus.is_blacklisted === '1' ? 'yes ⚠️' : 'no';
const isProxy = goplus.is_proxy === '1' ? 'yes ⚠️' : 'no';
const selfDestruct = goplus.selfdestruct === '1' ? 'yes ⚠️' : 'no';

// ---- Honeypot.is ----
let honeypot = {};
let honeypotAvailable = false;
try {
  honeypot = honeypotRaw || {};
  if (honeypot && (honeypot.honeypotResult || honeypot.simulationResult)) honeypotAvailable = true;
} catch (e) { honeypot = {}; }

const hpSimulationSuccess = honeypot.simulationSuccess === true ? 'success' : (honeypot.simulationSuccess === false ? 'failed ⚠️' : 'N/A');
const hpIsHoneypot = honeypot.honeypotResult && honeypot.honeypotResult.isHoneypot === true ? 'yes ⚠️' : (honeypot.honeypotResult ? 'no' : 'N/A');
const hpBuyTax = honeypot.simulationResult && honeypot.simulationResult.buyTax !== undefined ? honeypot.simulationResult.buyTax + '%' : 'N/A';
const hpSellTax = honeypot.simulationResult && honeypot.simulationResult.sellTax !== undefined ? honeypot.simulationResult.sellTax + '%' : 'N/A';
const hpTransferTax = honeypot.simulationResult && honeypot.simulationResult.transferTax !== undefined ? honeypot.simulationResult.transferTax + '%' : 'N/A';

// ---- Build the prompt (all English) ----
// Rules 1-15 cover: honeypot, taxes, mintable/selfdestruct/hidden owner, blacklist,
// wash trading, concentration, rug signals, liquidity anomalies, LP concentration, missing data.
const prompt = 'Analyze the following Base chain pool data.\n\n' +
'[Pool Basics]\n' +
'- Pair: ' + name + '\n' +
'- Pool address: ' + poolAddress + '\n' +
'- Liquidity: ' + liquidityLine + '\n' +
'- 24h volume: $' + volume24h.toFixed(2) + '\n' +
'- Created at: ' + createdAt + '\n\n' +
'[Contract Security (GoPlus)]' + (goplusAvailable ? '' : ' (NO DATA ⚠️)') + '\n' +
'- Honeypot: ' + isHoneypot + '\n' +
'- Buy tax: ' + buyTax + '\n' +
'- Sell tax: ' + sellTax + '\n' +
'- Mintable: ' + isMintable + '\n' +
'- Open source: ' + isOpenSource + '\n' +
'- Hidden owner: ' + hiddenOwner + '\n' +
'- Can take back ownership: ' + canTakeBack + '\n' +
'- Blacklist function: ' + isBlacklisted + '\n' +
'- Proxy contract: ' + isProxy + '\n' +
'- Self-destruct: ' + selfDestruct + '\n' +
'- Owner percent: ' + ownerPercent + '\n' +
'- Creator percent: ' + creatorPercent + '\n' +
'- Holder count: ' + holderCount + '\n' +
'- LP holder count: ' + lpHolderCount + '\n\n' +
'[Honeypot Simulation (Honeypot.is)]' + (honeypotAvailable ? '' : ' (NO DATA ⚠️)') + '\n' +
'- Simulation: ' + hpSimulationSuccess + '\n' +
'- Is honeypot: ' + hpIsHoneypot + '\n' +
'- Buy tax: ' + hpBuyTax + '\n' +
'- Sell tax: ' + hpSellTax + '\n' +
'- Transfer tax: ' + hpTransferTax + '\n\n' +
'[Trading Stats (last ' + totalTrades + ' trades)]\n' +
'- Unique wallets: ' + uniqueWallets + '\n' +
'- Unique wallet ratio: ' + uniqueRatio + '%\n' +
'- Top 8 most active wallets:\n' + topWallets + '\n\n' +
'[Last 25 Trades]\n' + recentTrades + '\n\n' +
'[OHLCV (last 30 candles)]\n' + candleLines + '\n\n' +
'Determine the risk level of this pool and flag the following red flags:\n' +
'1. GoPlus is_honeypot = 1 → verdict SCAM\n' +
'2. Sell tax > 10% → verdict SCAM\n' +
'3. Buy tax > 10% → at least SUSPICIOUS\n' +
'4. Mintable / self-destruct / hidden owner → at least SUSPICIOUS\n' +
'5. Blacklist function enabled → high risk\n' +
'6. Unique wallets / total trades < 15% → suspected wash-trading bots\n' +
'7. Top wallets dominate trade count → high concentration\n' +
'8. Same wallet rapidly buys and sells → wash trading\n' +
'9. Price drops more than 50% in a short window → rug pull signal\n' +
'10. Many trades but few unique wallets → bot activity\n' +
'11. Very low liquidity or anomalous liquidity → easy to manipulate\n' +
'12. Very few LP holders (e.g. < 3) → LP concentration, rug pull risk\n' +
'13. Honeypot.is simulation failed or flagged as honeypot → verdict SCAM\n' +
'14. If liquidity is flagged as anomalous, explicitly state the data may be manipulated\n' +
'15. If GoPlus or Honeypot.is returns no data, explicitly state that security data is missing, lower confidence, and never default to SAFE\n\n' +
'Respond with ONLY the following JSON and nothing else. All values must be in English.\n' +
'{\n' +
'  "verdict": "SAFE or SUSPICIOUS or SCAM",\n' +
'  "confidence": integer between 0 and 100,\n' +
'  "risk_tags": ["tag1", "tag2", "tag3"],\n' +
'  "analysis": "English analysis under 200 words explaining the reasoning, citing contract security findings",\n' +
'  "suggestion": "One-line action recommendation for the user in English"\n' +
'}';

return [{ json: {
  prompt: prompt,
  poolAddress: poolAddress,
  name: name,
  liquidity: liquidity,
  liquidityWarning: liquidityWarning,
  volume24h: volume24h,
  candles: candles,
  trades: trades,
  uniqueWallets: uniqueWallets,
  totalTrades: totalTrades
} }];

// Render the final result page.
// Security: every dynamic field (AI text, token name, on-chain values) goes through esc() to prevent XSS.
const resp = $input.first().json;
const prev = $('Build Prompt').first().json;

// HTML-escape helper to prevent XSS
function esc(v) {
  return String(v === undefined || v === null ? '' : v).replace(/[&<>"']/g, function(c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}

let ai = { verdict: 'ERROR', confidence: 0, risk_tags: [], analysis: 'Failed to parse AI response', suggestion: '' };
try {
  const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
  const clean = content.replace(/```json/g, '').replace(/```/g, '').trim();
  ai = Object.assign(ai, JSON.parse(clean));
} catch (e) {
  ai.analysis = 'Failed to parse AI response: ' + e.message;
}

const poolAddress = prev.poolAddress;
const name = prev.name;
const liquidity = prev.liquidity;
const liquidityWarning = prev.liquidityWarning || '';
const volume24h = prev.volume24h;
const candles = prev.candles || [];
const trades = prev.trades || [];

// Convert candles to ascending time order for lightweight-charts
const chartCandles = candles.map(function(c) {
  return { time: c[0], open: parseFloat(c[1]), high: parseFloat(c[2]), low: parseFloat(c[3]), close: parseFloat(c[4]) };
}).reverse();

const volumes = candles.map(function(c) {
  return { time: c[0], value: parseFloat(c[5]), color: parseFloat(c[4]) >= parseFloat(c[1]) ? 'rgba(16,185,129,0.5)' : 'rgba(239,68,68,0.5)' };
}).reverse();

// Auto-derive price precision from magnitude so tiny prices do not render as 0.+1234567890
let pricePrecision = 8;
if (chartCandles.length > 0) {
  const mp = Math.max.apply(null, chartCandles.map(function(c) { return c.high; }).concat([0]));
  if (mp > 0) {
    const m = Math.floor(Math.log10(mp));
    pricePrecision = Math.min(Math.abs(m) + 2, 18);
  }
}
const minMove = Math.pow(10, -pricePrecision);

// Trades table: first 30 rows only
const tradesHtml = trades.slice(0, 30).map(function(t) {
  const a = t.attributes || {};
  const kind = (a.kind || '').toLowerCase();
  const cls = kind === 'buy' ? 'buy' : 'sell';
  const time = (a.block_timestamp || '').replace('T', ' ').slice(0, 19);
  const usd = parseFloat(a.volume_in_usd || 0);
  const usdText = usd >= 1000 ? '$' + (usd / 1000).toFixed(2) + 'K' : '$' + usd.toFixed(2);
  const price = kind === 'buy'
    ? parseFloat(a.price_to_in_usd || 0)
    : parseFloat(a.price_from_in_usd || 0);
  const priceText = price > 0 ? price.toPrecision(6) : '-';
  const txHash = a.tx_hash || '';
  const txLink = txHash ? 'https://basescan.org/tx/' + encodeURIComponent(txHash) : '#';
  const fromAddr = a.tx_from_address || '';
  const fromShort = fromAddr.slice(0, 8) + '...' + fromAddr.slice(-4);
  const hashShort = txHash.slice(0, 10) + '...';
  return '<tr><td>' + esc(time) + '</td><td class="' + cls + '">' + esc(kind.toUpperCase()) + '</td><td>' + esc(usdText) + '</td><td>' + esc(priceText) + '</td><td><a href="' + txLink + '" target="_blank" rel="noopener">' + esc(hashShort) + '</a></td><td>' + esc(fromShort) + '</td></tr>';
}).join('');

const riskTagsHtml = (ai.risk_tags || []).map(function(t) { return '<span class="risk-tag">' + esc(t) + '</span>'; }).join('');

let verdictColor = '#6b7280';
if (ai.verdict === 'SAFE') verdictColor = '#10b981';
else if (ai.verdict === 'SUSPICIOUS') verdictColor = '#eab308';
else if (ai.verdict === 'SCAM') verdictColor = '#ef4444';

const verdictText = esc(ai.verdict || 'UNKNOWN');

const SO = '<' + 'script>';
const SC = '<' + '/script>';

const html = '<!DOCTYPE html>' +
'<html lang="en"><head><meta charset="UTF-8"><title>AI Analysis · ' + esc(name) + '</title>' +
'<' + 'script src="https://unpkg.com/lightweight-charts@4.1.0/dist/lightweight-charts.standalone.production.js">' + '<' + '/script>' +
'<style>' +
'*{box-sizing:border-box;margin:0;padding:0;}' +
'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#0f1117;color:#e5e7eb;padding:20px;}' +
'.header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:8px;}' +
'h1{color:#f59e0b;font-size:20px;display:flex;align-items:center;gap:10px;}' +
'.back-link{color:#60a5fa;text-decoration:none;font-size:14px;font-weight:600;}' +
'.back-link:hover{text-decoration:underline;}' +
'.address{color:#60a5fa;font-family:monospace;font-size:12px;word-break:break-all;}' +
'.address a{color:#60a5fa;text-decoration:none;}' +
'.pool-info-bar{display:flex;gap:20px;margin-bottom:16px;flex-wrap:wrap;background:#1a1d27;border-radius:8px;padding:12px 16px;}' +
'.pool-info-bar .item{font-size:13px;color:#9ca3af;}' +
'.pool-info-bar .item strong{color:#e5e7eb;margin-left:4px;}' +
'.warning{color:#ef4444;font-size:11px;margin-left:4px;}' +
'.ai-card{background:#1a1d27;border-radius:12px;padding:20px;margin-bottom:20px;border-left:5px solid ' + verdictColor + ';}' +
