'.trades-table th,.trades-table td{padding:6px 8px;text-align:left;border-bottom:1px solid #2d3142;}' +
'.trades-table th{color:#9ca3af;font-weight:600;}' +
'.trades-table a{color:#60a5fa;text-decoration:none;}' +
'.buy{color:#10b981;font-weight:600;}' +
'.sell{color:#ef4444;font-weight:600;}' +
'.footer{color:#6b7280;font-size:11px;margin-top:20px;text-align:center;line-height:1.7;}' +
'</style></head><body>' +
'<div class="header">' +
'<h1><a href="./base-pool-scanner" class="back-link">← Back</a>🤖 AI Pool Analysis</h1>' +
'<div class="address">Pool: <a href="https://www.geckoterminal.com/base/pools/' + encodeURIComponent(poolAddress) + '" target="_blank" rel="noopener">' + esc(poolAddress) + '</a></div>' +
'</div>' +
'<div class="pool-info-bar">' +
'<div class="item">Pair<strong>' + esc(name) + '</strong></div>' +
'<div class="item">Liquidity<strong>$' + esc(liquidity.toFixed(2)) + '</strong>' + (liquidityWarning ? '<span class="warning">' + esc(liquidityWarning) + '</span>' : '') + '</div>' +
'<div class="item">24h Volume<strong>$' + esc(volume24h.toFixed(2)) + '</strong></div>' +
'</div>' +
'<div class="ai-card">' +
'<div class="ai-header"><div>' +
'<div class="verdict">' + verdictText + '</div>' +
'<div class="confidence">Confidence<strong>' + esc((ai.confidence || 0) + '%') + '</strong>' +
'<div class="confidence-bar"><div class="confidence-fill" style="width:' + esc(ai.confidence || 0) + '%;"></div></div>' +
'</div></div></div>' +
(riskTagsHtml ? '<div class="risk-tags">' + riskTagsHtml + '</div>' : '') +
'<div class="ai-section"><div class="ai-section-label">Analysis</div>' +
'<div class="ai-section-text">' + esc(ai.analysis || '') + '</div></div>' +
'<div class="ai-section"><div class="ai-section-label">Suggestion</div>' +
'<div class="suggestion-box">' + esc(ai.suggestion || '') + '</div></div>' +
'</div>' +
'<div class="chart-section"><div class="section-title">📈 Price Chart</div><div id="chart"></div></div>' +
'<div class="chart-section"><div class="section-title">📜 Recent Trades</div>' +
'<table class="trades-table"><thead><tr><th>Time (UTC)</th><th>Side</th><th>Amount</th><th>Price</th><th>Tx</th><th>From</th></tr></thead>' +
'<tbody>' + tradesHtml + '</tbody></table></div>' +
'<div class="footer">Generated by Base Pool Risk Scanner · DeepSeek AI<br>Research only. Not investment advice.</div>' +
SO +
'var CANDLES = ' + JSON.stringify(chartCandles) + ';' +
'var VOLUMES = ' + JSON.stringify(volumes) + ';' +
'var PRECISION = ' + pricePrecision + ';' +
'var MINMOVE = ' + minMove + ';' +
'function initChart(){' +
'  if(typeof LightweightCharts === "undefined"){' +
'    document.getElementById("chart").innerHTML = "<div style=\'padding:40px;text-align:center;color:#6b7280;\'>Chart library failed to load (CDN blocked)</div>";' +
'    return;' +
'  }' +
'  var el = document.getElementById("chart");' +
'  var chart = LightweightCharts.createChart(el,{layout:{background:{color:"#0f1117"},textColor:"#9ca3af"},grid:{vertLines:{color:"#1f2333"},horzLines:{color:"#1f2333"}},timeScale:{borderColor:"#2d3142",timeVisible:true,secondsVisible:false},rightPriceScale:{borderColor:"#2d3142"},crosshair:{mode:LightweightCharts.CrosshairMode.Normal}});' +
'  var cs = chart.addCandlestickSeries({upColor:"#10b981",downColor:"#ef4444",borderUpColor:"#10b981",borderDownColor:"#ef4444",wickUpColor:"#10b981",wickDownColor:"#ef4444",priceFormat:{type:"price",precision:PRECISION,minMove:MINMOVE}});' +
'  cs.setData(CANDLES);' +
'  var vs = chart.addHistogramSeries({priceFormat:{type:"volume"},priceScaleId:""});' +
'  vs.priceScale().applyOptions({scaleMargins:{top:0.8,bottom:0}});' +
'  vs.setData(VOLUMES);' +
'  chart.timeScale().fitContent();' +
'  window.addEventListener("resize",function(){chart.applyOptions({width:el.clientWidth});});' +
'}' +
'initChart();' +
SC +
'</body></html>';

return [{ json: { html: html } }];
